// Visual prototype only: all players and results below are demonstration data.
const films=await fetch('movies.json').then(r=>r.json());
const names=['Саша','Аня','Миша','Катя'], tones=['#a5c7df','#d3b7a8','#b4c5ad','#c7b9d5'];
const variants=['A','B','C'], titles={A:'A · После сеанса',B:'B · Киноафиша',C:'C · Общий стол'};
let variant=new URLSearchParams(location.search).get('variant')||'A';if(!variants.includes(variant))variant='A';
let screen='home', entry='create', nickname='Саша', target=30, ratings={}, seconds=60, ticking=false, interval;
const ranks=['S','A','B','C','D'];
const clock=()=>Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');
const $=s=>document.querySelector(s), app=$('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avatar=(i,large='')=>`<span class="avatar ${large}" style="--tone:${tones[i]}">${['СШ','АН','МШ','КТ'][i]}</span>`;
const image=f=>`assets/${f.posterUrl.split('/').at(-1)}`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function go(s){screen=s;clearInterval(interval);ticking=false;render();window.scrollTo({top:0,behavior:'instant'})}
function fan(){return `<div class="film-fan">${films.map((f,i)=>`<button class="fan-poster" data-preview="${i}" style="--i:${i};--rise:${[0,11,19,11,0][i]};z-index:${[1,2,5,3,1][i]}" aria-label="${esc(f.title)}"><img src="${image(f)}" alt="${esc(f.title)}"></button>`).join('')}<div class="fan-note"><span></span>Знакомое кино. Непредсказуемые мнения.</div></div>`}
function home(){return `<div class="home-grid"><section class="hero"><span class="eyebrow">Игра о кино и тех, с кем его обсуждают</span><h1>У каждого<br> свой шедевр.</h1><p class="hero-intro">Соберите друзей, расставьте фильмы по&nbsp;местам и&nbsp;узнайте, чьи вкусы совпадают с&nbsp;вашими.</p>${fan()}</section><section class="entry-card"><h2 class="entry-heading">Вечер начинается здесь</h2><p class="entry-sub">Без регистрации. Только вы и ваша компания.</p><div class="tabs" role="tablist" aria-label="Способ входа"><button role="tab" aria-selected="${entry==='create'}" class="${entry==='create'?'active':''}" data-entry="create">Создать комнату</button><button role="tab" aria-selected="${entry==='join'}" class="${entry==='join'?'active':''}" data-entry="join">Войти по коду</button></div><form id="entry-form"><div class="field"><label for="nick">Как вас называть?</label><input id="nick" maxlength="15" placeholder="Ваш никнейм" value="${esc(nickname)}" required autocomplete="nickname"></div>${entry==='join'?'<div class="field"><label for="code">Код от друзей</label><input id="code" minlength="6" maxlength="6" placeholder="Например, KINO24" required style="text-transform:uppercase;letter-spacing:3px"></div>':''}<button class="primary full" type="submit">${entry==='create'?'Создать комнату':'Присоединиться'}<span class="arrow">↗</span></button></form><div class="entry-bottom"><span>От 2 до 16 игроков</span><button class="text-button" data-rules>Как играть?</button></div><div class="party-mini"><div class="avatar-pile">${[0,1,2].map(i=>avatar(i)).join('')}</div><p>Позовите тех, с кем<br>любите спорить о кино.</p></div></section><p class="home-caption">Пять фильмов в раунде / по одному рангу S–D / очки за совпадения</p></div>`}
function lobby(){return `<button class="back" data-screen="home">← В главное меню</button><div class="section-top"><div><div class="section-number">Комната KINO24</div><h1>Все свои. Почти в сборе.</h1><p>Приглашайте друзей. А фильмы мы уже подготовили.</p></div><button class="outlined" data-rules>Правила игры</button></div><div class="lobby-layout"><section class="panel"><div class="panel-title"><h2>Ваша компания</h2><span class="count">4 / 16 игроков</span></div>${names.map((n,i)=>`<div class="player-row">${avatar(i)}<div><strong>${esc(i===0?nickname:n)}${i===0?' <span class="quiet">(вы)</span>':''}</strong><small>${i===0?'Ведущий комнаты':'В комнате'}</small></div><span class="ready">На месте</span></div>`).join('')}<div class="invite-slot"><span>＋</span><p>Здесь ещё есть место.<br>Поделитесь кодом с друзьями.</p></div><div class="your-color">Ваш цвет<div class="swatches">${tones.map((t,i)=>`<button aria-label="Цвет ${i+1}" class="${i===0?'selected':''}" style="--c:${t}" data-color="${i}"></button>`).join('')}</div></div></section><aside class="panel settings"><h2 class="entry-heading">Билет в вашу комнату</h2><p style="margin-top:10px">Один код для всей компании</p><div class="room-code"><strong>KINO24</strong><button id="copy">Скопировать</button></div><div class="target-control"><div><p>Цель игры</p><span style="display:block;margin-top:7px;font-size:14px">До ${target} очков</span></div><div class="stepper"><button data-step="-5" aria-label="Уменьшить цель">−</button><button data-step="5" aria-label="Увеличить цель">+</button></div></div><div class="target-control"><p>Время на раунд</p><span style="font-size:14px">60 секунд</span></div><button class="primary full" id="start">Начать первый раунд <span class="arrow">↗</span></button><p class="note">Все на месте? Можно начинать.</p></aside></div>`}
function game(){return `<div class="game-header"><div><div class="section-number">Первый раунд / цель ${target} очков</div><h1>Какое кино — ваше?</h1><p>Один ранг для каждого фильма. Доверьтесь вкусу.</p></div><div class="timer"><strong id="clock">${clock()}</strong><button id="timer-toggle" aria-label="${ticking?'Пауза':'Запустить таймер'}">${ticking?'Ⅱ':'▷'}</button></div></div><div class="game-players">${names.map((n,i)=>`<div class="game-player">${avatar(i)}<span>${esc(i===0?nickname:n)}</span><small>${i===0?Object.keys(ratings).length+'/5':'оценивает'}</small></div>`).join('')}<span class="count" style="margin-left:auto">Комната KINO24</span></div><p class="swipe-hint">Листайте фильмы в сторону →</p><div class="film-grid">${films.map((f,i)=>`<article class="movie-card"><div class="poster"><img src="${image(f)}" alt="Постер ${esc(f.title)}">${ratings[i]?`<span class="rank-stamp">${ratings[i]}</span>`:''}</div><h2>${esc(f.title.replace(/ \(\d+\)/,''))}</h2><div class="movie-year">${f.title.match(/\d{4}/)?.[0]} · фильм ${i+1} из 5</div><div class="rank-options" role="group" aria-label="Оценить ${esc(f.title)}">${ranks.map(r=>`<button data-rate="${i}:${r}" aria-label="${r} для ${esc(f.title)}" aria-pressed="${ratings[i]===r}" class="${ratings[i]===r?'chosen':''}">${r}</button>`).join('')}</div></article>`).join('')}</div><div class="round-bottom"><div class="rating-progress">${Object.keys(ratings).length===5?'Все фильмы на своих местах':'Оценено '+Object.keys(ratings).length+' из 5'}<div class="progress-track"><span style="width:${Object.keys(ratings).length*20}%"></span></div></div><p class="round-help">S — шедевр, D — не моё. Если ранг занят, фильмы поменяются местами.</p><button class="primary" id="reveal">${Object.keys(ratings).length===5?'Посмотреть совпадения':'Завершить раунд'}<span class="arrow">↗</span></button></div>`}
function results(){return `<button class="back" data-screen="game">← Вернуться к фильмам</button><div class="results-layout"><section class="winner-feature"><div class="winner-orbit"><span class="winner-crown">♛</span>${avatar(0)}</div><span class="eyebrow">Демонстрация итогов</span><h1>Этот вечер — ваш.</h1><p>${esc(nickname)}, у вас ${demoScores()[0]} очков за совпадения.<br>Есть что обсудить после игры.</p></section><section><div class="panel-title"><h2>Как совпали ваши вкусы</h2><span class="count">4 игрока</span></div>${[0,2,3,1].map((i,position)=>`<div class="leader-row"><span class="place">${[1,2,2,4][position]}</span>${avatar(i)}<span>${esc(i===0?nickname:n)}${i===0?' <span class="quiet">(вы)</span>':''}</span><strong>${demoScores()[i]} <small>очков</small></strong></div>`).join('')}<div class="match-note">Самое единодушное решение — <strong>«Интерстеллар»</strong>. В демонстрации трое поставили ему S.</div><div class="results-actions"><button class="outlined" data-screen="home">В главное меню</button><button class="primary" id="again">Ещё один вечер <span class="arrow">↗</span></button></div></section></div>`}
// Four worked demonstration ballots; points are calculated by the game's match rule.
function demoScores(){const ballots=[['S','A','B','C','D'],['S','A','B','D','C'],['S','B','A','C','D'],['A','S','B','C','D']];return ballots.map((a,i)=>a.reduce((sum,r,m)=>sum+ballots.filter((b,j)=>j!==i&&b[m]===r).length,0))}
function render(){const scroll=$('.film-grid')?.scrollLeft||0;document.body.dataset.variant=variant;$('#variant-name').textContent=titles[variant];$('.screen-nav').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.screen===screen);b.setAttribute('aria-current',b.dataset.screen===screen?'page':'false')});app.innerHTML=({home,lobby,game,results}[screen])();if($('.film-grid'))$('.film-grid').scrollLeft=scroll;}
function changeVariant(delta){variant=variants[(variants.indexOf(variant)+delta+3)%3];const u=new URL(location);u.searchParams.set('variant',variant);history.replaceState(null,'',u);render()}
$('#previous').onclick=()=>changeVariant(-1);$('#next').onclick=()=>changeVariant(1);
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#rules').open)return;if(e.key==='ArrowRight')changeVariant(1);if(e.key==='ArrowLeft')changeVariant(-1)});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
if(b.dataset.screen){e.preventDefault();go(b.dataset.screen)}
if(b.hasAttribute('data-rules'))$('#rules').showModal();
if(b.matches('.dialog-close,.dialog-done'))$('#rules').close();
if(b.dataset.entry){nickname=$('#nick')?.value||nickname;entry=b.dataset.entry;render()}
if(b.dataset.preview)toast(films[b.dataset.preview].title);
if(b.dataset.color){document.querySelectorAll('.swatches button').forEach(el=>el.classList.toggle('selected',el===b));toast('Цвет выбран для демонстрации')}
if(b.dataset.step){target=Math.min(100,Math.max(5,target+Number(b.dataset.step)));render()}
if(b.id==='copy'){try{await navigator.clipboard.writeText('KINO24');toast('Код KINO24 скопирован')}catch{toast('Код комнаты: KINO24')}}
if(b.id==='start'){ratings={};seconds=60;go('game')}
if(b.id==='again')go('lobby');
if(b.id==='reveal')go('results');
if(b.dataset.rate){const [i,r]=b.dataset.rate.split(':'),other=Object.keys(ratings).find(k=>ratings[k]===r);const old=ratings[i];if(other!==undefined&&other!==i){if(old)ratings[other]=old;else delete ratings[other]}ratings[i]=r;if(Object.keys(ratings).length===4){const left=[0,1,2,3,4].find(k=>!ratings[k]);ratings[left]=ranks.find(r=>!Object.values(ratings).includes(r))}render()}
if(b.id==='timer-toggle'){ticking=!ticking;clearInterval(interval);if(ticking)interval=setInterval(()=>{seconds--;if(seconds<=0){go('results');return}$('#clock').textContent=clock()},1000);render()}
});
document.addEventListener('submit',e=>{if(e.target.id!=='entry-form')return;e.preventDefault();nickname=$('#nick').value.trim();if(!nickname)return;go('lobby');toast('Демонстрационная комната — без подключения к серверу')});
render();
// Three depth planes, frame-independent motion, capped DPR and a user-controlled pause.
const canvas=$('#rain'),ctx=canvas.getContext('2d');let w,h,drops=[],enabled=true,last=0,raf;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function resize(){w=innerWidth;h=innerHeight;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);drops=Array.from({length:Math.min(145,Math.floor(w/9))},()=>{const z=Math.random();return{x:Math.random()*w,y:Math.random()*h,z,speed:230+z*420,len:9+z*30}})}
function rain(t){const dt=Math.min((t-last)/1000,.035)||.016;last=t;ctx.clearRect(0,0,w,h);for(const d of drops){d.y+=d.speed*dt;d.x-=(25+d.z*40)*dt;if(d.y>h+40){d.y=-40;d.x=Math.random()*(w+80)}if(d.x<-40)d.x=w+30;ctx.strokeStyle=`rgba(165,199,223,${.045+d.z*.095})`;ctx.lineWidth=.45+d.z*.65;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-2-d.z*3,d.y+d.len);ctx.stroke()}raf=requestAnimationFrame(rain)}
function toggleRain(){cancelAnimationFrame(raf);if(enabled&&!reduced.matches&&!document.hidden){last=0;raf=requestAnimationFrame(rain)}else ctx.clearRect(0,0,w,h);$('#weather').setAttribute('aria-pressed',String(enabled&&!reduced.matches));$('#weather span:last-child').textContent=enabled&&!reduced.matches?'Дождь включён':'Дождь выключен'}
$('#weather').onclick=()=>{enabled=!enabled;toggleRain()};addEventListener('resize',resize);document.addEventListener('visibilitychange',toggleRain);reduced.addEventListener('change',toggleRain);resize();toggleRain();
